	// may already have exhausted its deadline; it must not cancel this hold.
	cleanupCtx, cleanupCancel := nativeHarnessCleanupReviewContext(ctx)
	defer cleanupCancel()
	nativeHarnessWrite(t, filepath.Join(cfg.OutputDirectory, "06-fixture-retained.ready.json"), Object{
		"test_failed": t.Failed(), "database": opt.Source, "release_required": true})
	nativeHarnessWait(t, cleanupCtx, filepath.Join(cfg.OutputDirectory, "06-release-fixture.approval.json"), "release-fixture")
